# dump-image.ps1 — unfreeze service, then dump loaded PE images WITHOUT suspending threads
# (MiniDumpWriteDump hangs on this target; a passive VirtualQueryEx+ReadProcessMemory walk
#  of MEM_IMAGE regions needs no thread suspension and triggers no anti-dump.)
$desk = "$env:USERPROFILE\Desktop"
$log = "$desk\dumpimg-status.log"
function L($m) { Add-Content -Path $log -Value ("[{0:HH:mm:ss}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) }
Set-Content -Path $log -Value ""

L "killing stuck dumper 6464"
try { Stop-Process -Id 6464 -Force -ErrorAction Stop; L "killed" } catch { L ("kill failed: " + $_.Exception.Message) }

L "restarting ASUSOptimization service to unfreeze"
try {
  Stop-Service -Name ASUSOptimization -Force -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 2
  Start-Service -Name ASUSOptimization -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 5
  L ("service state: " + (Get-Service ASUSOptimization).Status)
} catch { L ("service restart failed: " + $_.Exception.Message) }

$cs = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;

public static class ImgDump {
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr OpenProcess(uint a, bool i, int pid);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr VirtualQueryEx(IntPtr h, IntPtr addr, out MEMORY_BASIC_INFORMATION mbi, uint len);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool ReadProcessMemory(IntPtr h, IntPtr addr, byte[] b, uint sz, out IntPtr rd);
  [DllImport("psapi.dll", SetLastError = true)] public static extern bool EnumProcessModulesEx(IntPtr h, [Out] IntPtr[] m, uint cb, out uint need, uint filter);
  [DllImport("psapi.dll", CharSet = CharSet.Unicode)] public static extern uint GetModuleFileNameEx(IntPtr h, IntPtr m, StringBuilder sb, uint sz);

  [StructLayout(LayoutKind.Sequential)]
  public struct MEMORY_BASIC_INFORMATION {
    public IntPtr BaseAddress;
    public IntPtr AllocationBase;
    public uint AllocationProtect;
    public IntPtr RegionSize;
    public uint State;
    public uint Protect;
    public uint Type;
  }

  public static List<IntPtr> AsusModules(IntPtr h, int max) {
    IntPtr[] mods = new IntPtr[1024]; uint need;
    var list = new List<IntPtr>();
    if (EnumProcessModulesEx(h, mods, (uint)(mods.Length * IntPtr.Size), out need, 0x03)) {
      int n = (int)(need / IntPtr.Size);
      StringBuilder sb = new StringBuilder(1024);
      for (int i = 0; i < n && list.Count < max; i++) {
        sb.Length = 0;
        GetModuleFileNameEx(h, mods[i], sb, 1024);
        string f = sb.ToString();
        string low = f.ToLowerInvariant();
        if (low.Contains("asus") || low.Contains("asusopt") || low.Contains("asussci")) list.Add(mods[i]);
      }
    }
    return list;
  }

  // dump the PE image starting at modBase: walk VirtualQueryEx upward while in image range
  public static long DumpImage(IntPtr h, IntPtr modBase, string outPath, long maxBytes) {
    using (FileStream fs = new FileStream(outPath, FileMode.Create, FileAccess.Write)) {
      long written = 0;
      long addr = modBase.ToInt64();
      for (int guard = 0; guard < 4096 && written < maxBytes; guard++) {
        MEMORY_BASIC_INFORMATION mbi;
        if (VirtualQueryEx(h, (IntPtr)addr, out mbi, (uint)Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION))) == IntPtr.Zero) break;
        long size = mbi.RegionSize.ToInt64();
        if (size <= 0) break;
        // stop at a non-image region that is not part of the same allocation
        if (mbi.Type != 0x1000000 || mbi.AllocationBase != modBase) break;
        if (mbi.State == 0x1000 && mbi.Protect != 0x01) { // MEM_COMMIT, not NOACCESS
          byte[] buf = new byte[size];
          IntPtr rd;
          if (ReadProcessMemory(h, (IntPtr)addr, buf, (uint)size, out rd)) {
            fs.Write(buf, 0, (int)rd);
            written += (long)rd;
          }
        } else {
          fs.Write(new byte[size], 0, size); // reserve hole
          written += size;
        }
        addr += size;
      }
      return written;
    }
  }
}
'@
Add-Type -TypeDefinition $cs

$targets = @()
Get-Process AsusOptimization -ErrorAction SilentlyContinue | ForEach-Object { $targets += $_.Id }
Get-Process ArmouryCrate.Service -ErrorAction SilentlyContinue | ForEach-Object { $targets += $_.Id }
L ("dump targets: " + ($targets -join ","))

foreach ($procId in $targets) {
  $h = [ImgDump]::OpenProcess(0x0410, $false, $procId)  # VM_READ | QUERY info
  if ($h -eq [IntPtr]::Zero) { L ("open fail $procId err=" + [Runtime.InteropServices.Marshal]::GetLastWin32Error()); continue }
  $mods = [ImgDump]::AsusModules($h, 12)
  L ("pid=$procId asus modules: " + $mods.Count)
  foreach ($m in $mods) {
    $sb = New-Object System.Text.StringBuilder 1024
    [void][ImgDump]::GetModuleFileNameEx($h, $m, $sb, 1024)
    $name = [IO.Path]::GetFileName($sb.ToString())
    if (-not $name) { $name = "mod-" + $m.ToString() }
    $out = "$desk\imgdump-$procId-" + ($name -replace '[^a-zA-Z0-9._-]','_') + ".bin"
    $n = [ImgDump]::DumpImage($h, $m, $out, 200MB)
    L ("dumped $name -> " + [IO.Path]::GetFileName($out) + " ($n bytes)")
  }
  [void][ImgDump]::CloseHandle($h)
}
L "=== image dump complete ==="

# dump-image2.ps1 — dump every loaded PE image (MEM_IMAGE allocations) from the ASUS services.
# Name-filtering failed for these processes, so identify images by content: every contiguous
# MEM_IMAGE allocation starting with "MZ". No thread suspension (anti-dump safe).
$desk = "$env:USERPROFILE\Desktop"
$log = "$desk\dumpimg2-status.log"
function L($m) { Add-Content -Path $log -Value ("[{0:HH:mm:ss}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) }
Set-Content -Path $log -Value ""

$cs = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;

public static class ImgDump2 {
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr OpenProcess(uint a, bool i, int pid);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr VirtualQueryEx(IntPtr h, IntPtr addr, out MEMORY_BASIC_INFORMATION mbi, uint len);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool ReadProcessMemory(IntPtr h, IntPtr addr, byte[] b, uint sz, out IntPtr rd);

  [StructLayout(LayoutKind.Sequential)]
  public struct MEMORY_BASIC_INFORMATION {
    public IntPtr BaseAddress;
    public IntPtr AllocationBase;
    public uint AllocationProtect;
    public IntPtr RegionSize;
    public uint State;
    public uint Protect;
    public uint Type;
  }

  public static int DumpAllImages(IntPtr h, string outDir, string prefix, long maxPerImage) {
    long addr = 0x10000;
    int dumped = 0;
    var seen = new HashSet<long>();
    while (true) {
      MEMORY_BASIC_INFORMATION mbi;
      if (VirtualQueryEx(h, (IntPtr)addr, out mbi, (uint)Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION))) == IntPtr.Zero) break;
      long size = mbi.RegionSize.ToInt64();
      if (size <= 0) break;
      long base_ = mbi.AllocationBase.ToInt64();
      if (mbi.Type == 0x1000000 && !seen.Contains(base_)) {   // MEM_IMAGE allocation group
        seen.Add(base_);
        // read first 2 bytes to check MZ
        byte[] head = new byte[2];
        IntPtr rd;
        if (ReadProcessMemory(h, mbi.AllocationBase, head, 2, out rd) && rd.ToInt64() == 2 && head[0] == 0x4D && head[1] == 0x5A) {
          string path = Path.Combine(outDir, prefix + "-img-" + base_.ToString("x") + ".bin");
          long written = 0;
          long cur = base_;
          using (FileStream fs = new FileStream(path, FileMode.Create, FileAccess.Write)) {
            while (cur < base_ + (long)0x40000000) {  // walk the allocation group (max 1GB guard)
              MEMORY_BASIC_INFORMATION m2;
              if (VirtualQueryEx(h, (IntPtr)cur, out m2, (uint)Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION))) == IntPtr.Zero) break;
              long sz = m2.RegionSize.ToInt64();
              if (sz <= 0) break;
              if (m2.AllocationBase != mbi.AllocationBase) break;   // left the group
              if (m2.State == 0x1000 && m2.Protect != 0x01) {
                byte[] buf = new byte[sz];
                if (ReadProcessMemory(h, (IntPtr)cur, buf, (uint)sz, out rd)) {
                  fs.Write(buf, 0, (int)rd); written += (long)rd;
                }
              } else {
                fs.Write(new byte[sz], 0, (int)sz); written += sz;
              }
              cur += sz;
              if (written >= maxPerImage) break;
            }
          }
          Console.WriteLine("dumped " + path + " (" + written + " bytes)");
          dumped++;
        }
      }
      addr += size;
      if (addr < 0) break;  // wrapped past user space
      if (addr > 0x7FFFFFFFFFFF) break;
    }
    return dumped;
  }
}
'@
Add-Type -TypeDefinition $cs

foreach ($pname in 'AsusOptimization','ArmouryCrate.Service') {
  $p = Get-Process -Name $pname -ErrorAction SilentlyContinue | Select-Object -First 1
  if (-not $p) { L ("$pname not running"); continue }
  $h = [ImgDump2]::OpenProcess(0x0410, $false, $p.Id)
  if ($h -eq [IntPtr]::Zero) { L ("open fail $($p.Id) err=" + [Runtime.InteropServices.Marshal]::GetLastWin32Error()); continue }
  L ("dumping all images from $pname pid=$($p.Id) ...")
  $n = [ImgDump2]::DumpAllImages($h, $desk, $pname, 300MB)
  [void][ImgDump2]::CloseHandle($h)
  L ("$pname: $n images dumped")
}
L "=== image dump 2 complete ==="

